//! Node 24 parity vectors for the pi-js data modules: json, num, str16, b64, text, uri, crypto.
//!
//! `VECTORS` holds what Node 24.21 returned for each input (generated by a Node script; strings
//! that would contain lone surrogates were passed through `toWellFormed()`, matching the
//! U+FFFD rule of `pi_js::str16` and `pi_js::json::parse`).

use std::cmp::Ordering;
use std::sync::OnceLock;

use pi_js::{b64, crypto, json, num, str16, text, uri};
use serde_json::Value;

fn vectors() -> &'static Value {
    static V: OnceLock<Value> = OnceLock::new();
    V.get_or_init(|| serde_json::from_str(VECTORS).expect("vectors are valid JSON"))
}

fn cases(key: &str) -> &'static [Value] {
    vectors()[key]
        .as_array()
        .map(Vec::as_slice)
        .unwrap_or_else(|| panic!("missing vector set {key}"))
}

fn s(v: &Value) -> &str {
    v.as_str().unwrap_or_else(|| panic!("expected a string, got {v}"))
}

fn f64_from_bits(v: &Value) -> f64 {
    f64::from_bits(u64::from_str_radix(s(v), 16).expect("hex bits"))
}

fn same_f64(a: f64, b: f64) -> bool {
    (a.is_nan() && b.is_nan()) || a.to_bits() == b.to_bits()
}

fn bytes(v: &Value) -> Vec<u8> {
    v.as_array()
        .expect("byte array")
        .iter()
        .map(|b| b.as_u64().expect("byte") as u8)
        .collect()
}

fn code_points(s: &str) -> Vec<u64> {
    s.chars().map(|c| u64::from(u32::from(c))).collect()
}

fn u64s(v: &Value) -> Vec<u64> {
    v.as_array()
        .expect("array")
        .iter()
        .map(|x| x.as_u64().expect("u64"))
        .collect()
}

/// Collects mismatches so one run reports all of them.
#[derive(Default)]
struct Failures(Vec<String>);

impl Failures {
    fn check(&mut self, ok: bool, what: impl FnOnce() -> String) {
        if !ok {
            self.0.push(what());
        }
    }

    fn finish(self) {
        assert!(
            self.0.is_empty(),
            "{} mismatch(es):\n{}",
            self.0.len(),
            self.0.join("\n")
        );
    }
}

/// Compares a `Result` against a Node `{ok}` / `{err, name}` record.
fn check_result<T: PartialEq + std::fmt::Debug>(
    f: &mut Failures,
    label: &str,
    got: pi_js::error::Result<T>,
    expected: &Value,
    ok_value: impl Fn(&Value) -> T,
) {
    match (&got, expected.get("ok")) {
        (Ok(v), Some(e)) => {
            let e = ok_value(e);
            f.check(*v == e, || format!("{label}: got {v:?}, want {e:?}"));
        }
        (Err(err), None) => {
            let (name, message) = (s(&expected["name"]), s(&expected["err"]));
            f.check(err.name() == name && err.message() == message, || {
                format!(
                    "{label}: got error {}: {}, want {name}: {message}",
                    err.name(),
                    err.message()
                )
            });
            if let Some(code) = expected.get("code").and_then(Value::as_str) {
                f.check(err.code() == Some(code), || {
                    format!("{label}: got code {:?}, want {code}", err.code())
                });
            }
        }
        (Ok(v), None) => f.0.push(format!("{label}: got {v:?}, want error {expected}")),
        (Err(err), Some(_)) => {
            f.0.push(format!("{label}: got error {}, want {expected}", err.to_js_string()))
        }
    }
}

#[test]
fn json_parse_matches_node() {
    let mut f = Failures::default();
    for c in cases("json_parse") {
        let input = s(&c["input"]);
        let got = json::parse(input).map(|v| json::stringify(&v));
        check_result(&mut f, &format!("JSON.parse({input:?})"), got, c, |e| s(e).to_string());
    }
    f.finish();
}

#[test]
fn json_stringify_matches_node() {
    let mut f = Failures::default();
    for c in cases("json_stringify") {
        let src = s(&c["src"]);
        let v: Value = serde_json::from_str(src).expect("serde_json parses the source");
        let got = json::stringify(&v);
        f.check(got == s(&c["compact"]), || {
            format!("stringify({src}): got {got}, want {}", c["compact"])
        });
        for p in c["pretty"].as_array().expect("pretty") {
            let (indent, want) = (s(&p[0]), s(&p[1]));
            let got = json::stringify_pretty(&v, indent);
            f.check(got == want, || {
                format!("stringify({src}, null, {indent:?}): got {got:?}, want {want:?}")
            });
        }
    }
    f.finish();
}

#[test]
fn numbers_match_node() {
    let mut f = Failures::default();
    for c in cases("num") {
        let x = f64_from_bits(&c["bits"]);
        let want = s(&c["str"]);
        let got = num::to_js_string(x);
        f.check(got == want, || format!("String({x:e}): got {got}, want {want}"));
        let got = json::number_to_string(x);
        f.check(got == want, || {
            format!("number_to_string({x:e}): got {got}, want {want}")
        });
        let got = json::stringify(&x);
        f.check(got == s(&c["json"]), || {
            format!("JSON.stringify({x:e}): got {got}, want {}", c["json"])
        });
        for d in c["fixed"].as_array().expect("fixed") {
            let digits = d[0].as_u64().expect("digits") as u32;
            let got = num::to_fixed(x, digits);
            f.check(got == s(&d[1]), || {
                format!("({x:e}).toFixed({digits}): got {got}, want {}", d[1])
            });
        }
        for p in c["precision"].as_array().expect("precision") {
            let precision = p[0].as_u64().expect("precision") as u32;
            let got = num::to_precision(x, precision);
            f.check(got == s(&p[1]), || {
                format!("({x:e}).toPrecision({precision}): got {got}, want {}", p[1])
            });
        }
        let got = num::math_round(x);
        let want = f64_from_bits(&c["round"]);
        f.check(same_f64(got, want), || {
            format!("Math.round({x:e}): got {got:e}, want {want:e}")
        });
        let got = num::to_int32(x);
        f.check(i64::from(got) == c["int32"].as_i64().expect("int32"), || {
            format!("({x:e}) | 0: got {got}, want {}", c["int32"])
        });
        let got = num::to_uint32(x);
        f.check(u64::from(got) == c["uint32"].as_u64().expect("uint32"), || {
            format!("({x:e}) >>> 0: got {got}, want {}", c["uint32"])
        });
        f.check(num::is_integer(x) == c["is_integer"].as_bool().expect("bool"), || {
            format!("Number.isInteger({x:e})")
        });
        f.check(
            num::is_safe_integer(x) == c["is_safe_integer"].as_bool().expect("bool"),
            || format!("Number.isSafeInteger({x:e})"),
        );
    }
    for c in cases("to_string_radix") {
        let x = f64_from_bits(&c["bits"]);
        for e in c["out"].as_array().expect("out") {
            let radix = e[0].as_u64().expect("radix") as u32;
            let got = num::to_string_radix(x, radix);
            f.check(got == s(&e[1]), || {
                format!("({x:e}).toString({radix}): got {got}, want {}", e[1])
            });
        }
    }
    for c in cases("imul") {
        let (a, b, want) = (
            c[0].as_i64().unwrap() as i32,
            c[1].as_i64().unwrap() as i32,
            c[2].as_i64().unwrap(),
        );
        let got = num::imul(a, b);
        f.check(i64::from(got) == want, || {
            format!("Math.imul({a}, {b}): got {got}, want {want}")
        });
    }
    f.finish();
}

#[test]
fn parse_int_matches_node() {
    let mut f = Failures::default();
    for c in cases("parse_int") {
        let input = s(&c["s"]);
        for r in c["out"].as_array().expect("out") {
            let radix = r[0].as_u64().map(|r| r as u32);
            let want = f64_from_bits(&r[1]);
            let got = num::parse_int(input, radix);
            // Generic radices accumulate rounding error above 2^53, and Node's result depends on
            // whether the C++ build fused the multiply-add (arm64 does; the vectors come from
            // an arm64 Node).
            let generic = radix.is_some_and(|r| ![0, 2, 4, 8, 10, 16, 32].contains(&r));
            if generic && want.abs() > 9007199254740992.0 && !cfg!(target_arch = "aarch64") {
                continue;
            }
            f.check(same_f64(got, want), || {
                format!("parseInt({input:?}, {radix:?}): got {got:e}, want {want:e}")
            });
        }
    }
    f.finish();
}

#[test]
fn parse_float_and_number_match_node() {
    let mut f = Failures::default();
    for c in cases("parse_float") {
        let input = s(&c["s"]);
        let (got, want) = (num::parse_float(input), f64_from_bits(&c["parse_float"]));
        f.check(same_f64(got, want), || {
            format!("parseFloat({input:?}): got {got:e}, want {want:e}")
        });
        let (got, want) = (num::number(input), f64_from_bits(&c["number"]));
        f.check(same_f64(got, want), || {
            format!("Number({input:?}): got {got:e}, want {want:e}")
        });
    }
    f.finish();
}

#[test]
fn str16_matches_node() {
    let mut f = Failures::default();
    for c in cases("str16") {
        let v = s(&c["s"]);
        let want_len = c["len"].as_u64().expect("len") as usize;
        f.check(str16::len(v) == want_len, || {
            format!("{v:?}.length: got {}, want {want_len}", str16::len(v))
        });
        for e in c["slice"].as_array().expect("slice") {
            let (a, b) = (e[0].as_i64().expect("start"), e[1].as_i64());
            let got = str16::slice(v, a, b);
            f.check(got == s(&e[2]), || {
                format!("{v:?}.slice({a}, {b:?}): got {got:?}, want {}", e[2])
            });
        }
        for e in c["substring"].as_array().expect("substring") {
            let (a, b) = (
                e[0].as_u64().expect("start") as usize,
                e[1].as_u64().map(|b| b as usize),
            );
            let got = str16::substring(v, a, b);
            f.check(got == s(&e[2]), || {
                format!("{v:?}.substring({a}, {b:?}): got {got:?}, want {}", e[2])
            });
        }
        for (i, e) in c["char_code_at"].as_array().expect("char_code_at").iter().enumerate() {
            let got = str16::char_code_at(v, i).map(u64::from);
            f.check(got == e.as_u64(), || {
                format!("{v:?}.charCodeAt({i}): got {got:?}, want {e}")
            });
        }
        for e in c["index_of"].as_array().expect("index_of") {
            let (needle, from) = (s(&e[0]), e[1].as_u64().expect("from") as usize);
            let want = usize::try_from(e[2].as_i64().expect("index")).ok();
            let got = str16::index_of(v, needle, from);
            f.check(got == want, || {
                format!("{v:?}.indexOf({needle:?}, {from}): got {got:?}, want {want:?}")
            });
        }
        for e in c["last_index_of"].as_array().expect("last_index_of") {
            let needle = s(&e[0]);
            let want = usize::try_from(e[1].as_i64().expect("index")).ok();
            let got = str16::last_index_of(v, needle);
            f.check(got == want, || {
                format!("{v:?}.lastIndexOf({needle:?}): got {got:?}, want {want:?}")
            });
        }
        for e in c["last_index_of_from"].as_array().expect("last_index_of_from") {
            let (needle, from) = (s(&e[0]), e[1].as_u64().expect("from") as usize);
            let want = usize::try_from(e[2].as_i64().expect("index")).ok();
            let got = str16::last_index_of_from(v, needle, from);
            f.check(got == want, || {
                format!("{v:?}.lastIndexOf({needle:?}, {from}): got {got:?}, want {want:?}")
            });
        }
        for (i, e) in c["char_at"].as_array().expect("char_at").iter().enumerate() {
            let got = str16::char_at(v, i);
            f.check(got == s(e), || format!("{v:?}.charAt({i}): got {got:?}, want {e}"));
        }
        for (i, e) in c["code_point_at"].as_array().expect("code_point_at").iter().enumerate() {
            let got = str16::code_point_at(v, i).map(u64::from);
            f.check(got == e.as_u64(), || {
                format!("{v:?}.codePointAt({i}): got {got:?}, want {e}")
            });
        }
        for e in c["pad"].as_array().expect("pad") {
            let (n, fill) = (e[0].as_u64().expect("len") as usize, s(&e[1]));
            let got = str16::pad_start(v, n, fill);
            f.check(got == s(&e[2]), || {
                format!("{v:?}.padStart({n}, {fill:?}): got {got:?}, want {}", e[2])
            });
            let got = str16::pad_end(v, n, fill);
            f.check(got == s(&e[3]), || {
                format!("{v:?}.padEnd({n}, {fill:?}): got {got:?}, want {}", e[3])
            });
        }
    }
    for c in cases("trim") {
        let v = s(&c[0]);
        f.check(str16::trim(v) == s(&c[1]), || {
            format!("{v:?}.trim(): got {:?}", str16::trim(v))
        });
        f.check(str16::trim_start(v) == s(&c[2]), || {
            format!("{v:?}.trimStart(): got {:?}", str16::trim_start(v))
        });
        f.check(str16::trim_end(v) == s(&c[3]), || {
            format!("{v:?}.trimEnd(): got {:?}", str16::trim_end(v))
        });
    }
    let ws = u64s(&vectors()["whitespace"]);
    for c in (0u32..=0xFFFF).filter_map(char::from_u32) {
        let want = ws.contains(&u64::from(u32::from(c)));
        f.check(str16::is_js_whitespace(c) == want, || {
            format!("is_js_whitespace({:#06x}) != {want}", u32::from(c))
        });
    }
    for c in cases("cmp") {
        let (a, b) = (s(&c[0]), s(&c[1]));
        let want = match c[2].as_i64().expect("ordering") {
            -1 => Ordering::Less,
            0 => Ordering::Equal,
            _ => Ordering::Greater,
        };
        let got = str16::cmp(a, b);
        f.check(got == want, || format!("cmp({a:?}, {b:?}): got {got:?}, want {want:?}"));
    }
    f.finish();
}

#[test]
fn base64_matches_node() {
    let mut f = Failures::default();
    for c in cases("b64_decode") {
        let input = s(&c["s"]);
        let got = b64::decode(input);
        f.check(got == bytes(&c["b64"]), || {
            format!("Buffer.from({input:?}, 'base64'): got {got:?}, want {}", c["b64"])
        });
        let got = b64::decode_url(input);
        f.check(got == bytes(&c["b64url"]), || {
            format!("Buffer.from({input:?}, 'base64url'): got {got:?}, want {}", c["b64url"])
        });
        let got = b64::atob(input).map(|s| code_points(&s));
        check_result(&mut f, &format!("atob({input:?})"), got, &c["atob"], u64s);
    }
    for c in cases("b64_encode") {
        let input = bytes(&c["bytes"]);
        let got = b64::encode(&input);
        f.check(got == s(&c["b64"]), || {
            format!("base64 {input:?}: got {got}, want {}", c["b64"])
        });
        let got = b64::encode_url(&input);
        f.check(got == s(&c["url"]), || {
            format!("base64url {input:?}: got {got}, want {}", c["url"])
        });
    }
    for c in cases("btoa") {
        let input = s(&c["s"]);
        check_result(&mut f, &format!("btoa({input:?})"), b64::btoa(input), c, |e| {
            s(e).to_string()
        });
    }
    f.finish();
}

#[test]
fn text_decoder_matches_node() {
    let mut f = Failures::default();
    for c in cases("text") {
        let input = bytes(&c["b"]);
        let got = code_points(&text::decode_utf8(&input));
        f.check(got == u64s(&c["td"]), || {
            format!("TextDecoder {input:x?}: got {got:x?}, want {}", c["td"])
        });
        let got = code_points(&text::Utf8StreamDecoder::new().decode(&input, false));
        f.check(got == u64s(&c["td"]), || {
            format!("Utf8StreamDecoder {input:x?}: got {got:x?}, want {}", c["td"])
        });
        let got = code_points(&text::buffer_to_string(&input));
        f.check(got == u64s(&c["buf"]), || {
            format!("Buffer#toString {input:x?}: got {got:x?}, want {}", c["buf"])
        });
        let options = text::TextDecoderOptions {
            fatal: false,
            ignore_bom: true,
        };
        let got = code_points(&text::Utf8StreamDecoder::with_options(options).decode(&input, false));
        f.check(got == u64s(&c["ignore_bom"]), || {
            format!("ignoreBOM {input:x?}: got {got:x?}, want {}", c["ignore_bom"])
        });
        let got = code_points(&text::latin1_to_string(&input));
        f.check(got == u64s(&c["latin1"]), || {
            format!("latin1 {input:x?}: got {got:x?}, want {}", c["latin1"])
        });
        let got = code_points(&text::ascii_to_string(&input));
        f.check(got == u64s(&c["ascii"]), || {
            format!("ascii {input:x?}: got {got:x?}, want {}", c["ascii"])
        });
        let options = text::TextDecoderOptions {
            fatal: true,
            ignore_bom: false,
        };
        let got = text::Utf8StreamDecoder::with_options(options)
            .try_decode(&input, false)
            .map(|s| code_points(&s));
        check_result(&mut f, &format!("fatal {input:x?}"), got, &c["fatal"], u64s);
    }
    for c in cases("text_stream") {
        let mut d = text::Utf8StreamDecoder::new();
        let chunks = c["chunks"].as_array().expect("chunks");
        let outs = c["outs"].as_array().expect("outs");
        for (i, chunk) in chunks.iter().enumerate() {
            let got = code_points(&d.decode(&bytes(chunk), true));
            f.check(got == u64s(&outs[i]), || {
                format!("stream chunk {i} of {chunks:?}: got {got:x?}, want {}", outs[i])
            });
        }
        let got = code_points(&d.decode(&[], false));
        let last = &outs[chunks.len()];
        f.check(got == u64s(last), || {
            format!("stream flush of {chunks:?}: got {got:x?}, want {last}")
        });
        let got = code_points(&d.decode(&[0xef, 0xbb, 0xbf, 0x62], false));
        f.check(got == u64s(&c["again"]), || {
            format!("decode after flush: got {got:x?}, want {}", c["again"])
        });
    }
    f.finish();
}

#[test]
fn uri_matches_node() {
    let mut f = Failures::default();
    for c in cases("uri_encode") {
        let input = s(&c["s"]);
        let got = uri::encode_uri_component(input);
        f.check(got == s(&c["component"]), || {
            format!("encodeURIComponent({input:?}): got {got}")
        });
        let got = uri::encode_uri(input);
        f.check(got == s(&c["uri"]), || format!("encodeURI({input:?}): got {got}"));
    }
    for c in cases("uri_decode") {
        let input = s(&c["t"]);
        let label = format!("decodeURIComponent({input:?})");
        check_result(&mut f, &label, uri::decode_uri_component(input), &c["component"], |e| {
            s(e).to_string()
        });
        let label = format!("decodeURI({input:?})");
        check_result(&mut f, &label, uri::decode_uri(input), &c["uri"], |e| s(e).to_string());
    }
    f.finish();
}

#[test]
fn sha256_matches_node() {
    for c in cases("sha256") {
        let (input, want) = (s(&c[0]), s(&c[1]));
        assert_eq!(crypto::sha256_hex(input.as_bytes()), want, "sha256({input:?})");
        let hex: String = crypto::sha256(input.as_bytes())
            .iter()
            .map(|b| format!("{b:02x}"))
            .collect();
        assert_eq!(hex, want, "sha256({input:?}) bytes");
    }
}

